export const BODY: string = "\n<p>تصویر کا فارمیٹ بدلنے سے اکثر معیار بھی بدل جاتا ہے، مگر ہمیشہ نہیں۔ کبھی تبدیلی بالکل محفوظ ہوتی ہے، کبھی ہلکا سا نقصان ہوتا ہے، اور کبھی تصویر ہمیشہ کے لیے خراب ہو جاتی ہے۔</p>\n<p>فرق سمجھنے کے لیے نقصان دہ اور بغیر نقصان والے کمپریشن کا فرق جاننا ضروری ہے۔ یہی فرق طے کرتا ہے کہ کون سی تبدیلی محفوظ ہے اور کون سی تصویر کو نقصان پہنچائے گی۔</p>\n<p>یہ مضمون ہر بڑے فارمیٹ کی سچائی، بار بار تبدیلی کا نقصان، کام کرنے والی معیار سیٹنگز اور اصل فائل محفوظ رکھنے کا طریقہ بتاتا ہے۔ تبدیلی کے لیے <a href=\"/ur/tasveer-convert-karein/\">امیج کنورٹر</a> استعمال کریں۔</p>\n<h2 id=\"what-quality-loss-means\">معیار کا نقصان اصل میں کیا ہے</h2>\n<p>معیار کا نقصان وہ تفصیل ہے جو کمپریشن کے دوران ہمیشہ کے لیے پھینک دی جاتی ہے۔ آنکھ جن باریک رنگوں اور ہلکے سایوں کو مشکل سے دیکھتی ہے، کمپریسر انہی کو پہلے ہٹاتا ہے۔</p>\n<p>ہلکا نقصان اکثر نظر نہیں آتا، مگر بھاری نقصان رنگوں کی پٹیاں، دھندلے کنارے اور عجیب دھبے پیدا کرتا ہے۔ ایک بار پھینکی گئی تفصیل دوبارہ نہیں بنائی جا سکتی۔</p>\n<h2 id=\"lossy-vs-lossless\">نقصان دہ بمقابلہ بغیر نقصان: بنیادی فرق</h2>\n<p>نقصان دہ کمپریشن تفصیل پھینک کر فائل چھوٹی کرتی ہے، جیسے JPG اور WebP کا نقصان دہ موڈ۔ بغیر نقصان والی کمپریشن تمام تفصیل بچا کر فائل چھوٹی کرتی ہے، جیسے PNG۔</p>\n<p>نقصان دہ فارمیٹ چھوٹی فائل دیتا ہے، مگر ہر بار محفوظ کرنے پر کچھ کھوتا ہے۔ بغیر نقصان والا فارمیٹ بڑی فائل دیتا ہے، مگر بار بار محفوظ کرنے پر بھی تصویر ویسی ہی رہتی ہے۔</p>\n<h2 id=\"jpg-quality-explained\">JPG معیار، ایمانداری سے سمجھایا گیا</h2>\n<p>JPG کا معیار 1 سے 100 تک ہوتا ہے، اور 80 سے 90 کے درمیان اکثر بہترین توازن ملتا ہے۔ 90 سے اوپر فائل بہت بڑی ہو جاتی ہے اور فرق مشکل سے نظر آتا ہے۔</p>\n<p>70 سے نیچے معیار تیزی سے گرتا ہے: آسمان میں پٹیاں، چہرے پر دھبے اور متن کے گرد ہالہ نظر آنے لگتا ہے۔ تھمب نیل کے لیے 70 کافی ہو سکتا ہے، مگر مرکزی تصویر کے لیے 80 سے کم نہ جائیں۔</p>\n<h2 id=\"png-lossless-truth\">PNG: بغیر نقصان، مگر جادو نہیں</h2>\n<p>PNG ہر پکسل بالکل محفوظ رکھتا ہے، اس لیے اس میں معیار کا نقصان نہیں ہوتا۔ لیکن PNG تصویر کو بہتر نہیں بناتا: خراب JPG کو PNG میں بدلنے سے خرابی ویسی ہی رہتی ہے، صرف فائل بڑی ہو جاتی ہے۔</p>\n<p>PNG تصویروں کے لیے بھاری ہوتا ہے، کیونکہ وہ تفصیل پھینکتا نہیں۔ اسکرین شاٹ اور گرافکس کے لیے PNG بہترین ہے، مگر عام تصویروں کے لیے JPG یا WebP زیادہ سمجھدار انتخاب ہے۔</p>\n<h2 id=\"webp-best-of-both\">WebP: دونوں جہانوں کی بہترین چیز؟</h2>\n<p>WebP نقصان دہ اور بغیر نقصان دونوں موڈ دیتا ہے، اور شفافیت بھی بچاتا ہے۔ اسی معیار پر WebP JPG سے 25 سے 35 فیصد چھوٹا ہوتا ہے، اس لیے ویب کے لیے یہ اکثر بہترین انتخاب ہے۔</p>\n<p>لیکن WebP ہر جگہ قبول نہیں ہوتا، خاص طور پر پرانے سافٹ ویئر اور پرنٹرز میں۔ ویب کے لیے WebP چنیں، مگر اہم فائل کی JPG نقل بھی محفوظ رکھیں۔</p>\n<h2 id=\"heic-efficiency\">HEIC کی کارکردگی اور اس کی حدود</h2>\n<p>HEIC JPG سے تقریباً آدھی جگہ میں وہی معیار دیتا ہے، اس لیے آئی فون اسے پہلے سے طے شدہ فارمیٹ کے طور پر استعمال کرتا ہے۔ یہ جدید اور کارآمد فارمیٹ ہے۔</p>\n<p>اس کی حد مطابقت ہے: بہت سے ونڈوز پروگرام، ویب سائٹس اور پرنٹر HEIC نہیں کھولتے۔ شیئر کرنے سے پہلے HEIC کو JPG یا PNG میں بدل لینا محفوظ رہتا ہے۔</p>\n<h2 id=\"lossy-to-lossless-myth\">نقصان دہ سے بغیر نقصان والا بنانے کا فریب</h2>\n<p>JPG کو PNG میں بدلنے سے کھوئی ہوئی تفصیل واپس نہیں آتی۔ PNG صرف وہی بچاتا ہے جو JPG میں باقی ہے، اور خرابی بھی ساتھ محفوظ ہو جاتی ہے۔</p>\n<p>یہ تبدیلی صرف اس وقت مفید ہے جب آپ کو مزید ایڈیٹنگ کے لیے بغیر نقصان والا فارمیٹ چاہیے۔ معیار بہتر کرنے کے لیے یہ تبدیلی وقت ضائع کرنا ہے۔</p>\n<h2 id=\"repeated-conversions\">بار بار تبدیلی کیوں نقصان دیتی ہے</h2>\n<p>ہر نقصان دہ تبدیلی کچھ تفصیل پھینکتی ہے۔ JPG کو بار بار JPG میں بدلنے سے ہر نسل میں معیار گرتا ہے، جیسے فوٹو کاپی کی فوٹو کاپی۔</p>\n<p>اسے نسل کا مسئلہ کہتے ہیں: پہلی تبدیلی شاید نظر نہ آئے، مگر پانچویں تبدیلی پر رنگوں کی پٹیاں اور دھندلا پن صاف نظر آنے لگتا ہے۔ ہمیشہ اصل سے تبدیل کریں، نقل سے نہیں۔</p>\n<h2 id=\"quality-settings-that-work\">معیار کی سیٹنگز جو واقعی کام کرتی ہیں</h2>\n<p>ویب تصویروں کے لیے 80 سے 85 اچھا توازن ہے: فائل چھوٹی اور تصویر تیز۔ پرنٹ کے لیے 90 سے 95 چنیں، کیونکہ کاغذ پر ہلکا نقصان بھی نظر آتا ہے۔</p>\n<p>اسکرین شاٹ اور متن والی تصویر کے لیے 90 یا اس سے زیادہ رکھیں، کیونکہ متن کے کنارے سب سے پہلے خراب ہوتے ہیں۔ ہر بار نتیجہ کو مکمل سائز میں دیکھ کر تصدیق کریں۔</p>\n<h2 id=\"checking-visible-damage\">نظر آنے والا نقصان کیسے پہچانیں</h2>\n<p>نقصان دیکھنے کے لیے تصویر کو 100 فیصد زوم پر دیکھیں اور آسمان، جلد اور متن کے کنارے جانچیں۔ رنگوں کی پٹیاں اور عجیب چوکور دھبے نقصان کی پہلی نشانیاں ہیں۔</p>\n<p>چھوٹے پیش منظر پر نقصان چھپ جاتا ہے، اس لیے فیصلہ ہمیشہ مکمل سائز پر کریں۔ اگر مکمل سائز پر تصویر صاف لگے تو ویب کے لیے وہ کافی ہے۔</p>\n<h2 id=\"when-conversion-is-safe\">تبدیلی کب مکمل محفوظ ہے</h2>\n<p>بغیر نقصان والے فارمیٹوں کے درمیان تبدیلی محفوظ ہے، جیسے PNG سے WebP بغیر نقصان موڈ میں۔ اسی طرح اصل سے ایک بار نقصان دہ تبدیلی بھی محفوظ ہے، اگر معیار 80 سے اوپر ہو۔</p>\n<p>محفوظ تبدیلی کی پہچان یہ ہے کہ آپ اصل فائل محفوظ رکھیں۔ اگر نتیجہ پسند نہ آئے تو اصل سے دوبارہ تبدیل کر سکتے ہیں، بغیر کسی نقصان کے۔</p>\n<h2 id=\"when-to-keep-the-original\">اصل کب رکھنی چاہیے</h2>\n<p>اصل ہمیشہ رکھنی چاہیے، خاص طور پر خاندانی تصویروں، کلائنٹ کے کام اور پرنٹ کے لیے۔ اصل وہ واحد فائل ہے جس سے ہر مستقبل کی تبدیلی صاف بنے گی۔</p>\n<p>اصل کو الگ فولڈر میں رکھیں اور اس پر کبھی براہ راست ایڈیٹ نہ کریں۔ نقل پر کام کریں، اصل کو محفوظ رکھیں، اور ہر نئی ضرورت پر اصل سے نیا نسخہ بنائیں۔</p>\n<h2 id=\"generation-problem\">نسل کا مسئلہ سادہ الفاظ میں</h2>\n<p>نسل کا مسئلہ یہ ہے کہ ہر نقصان دہ محفوظ کرنے پر تصویر تھوڑی خراب ہوتی ہے۔ پہلی نسل اصل جیسی لگتی ہے، دوسری میں ہلکا فرق، اور پانچویں میں واضح خرابی نظر آتی ہے۔</p>\n<p>حل یہ ہے کہ ایڈیٹنگ بغیر نقصان والے فارمیٹ میں کریں اور آخری برآمد صرف ایک بار نقصان دہ فارمیٹ میں کریں۔ اس طرح تصویر صرف ایک نسل کا نقصان اٹھاتی ہے۔</p>\n<h2 id=\"lossy-formats-compared\">نقصان دہ فارمیٹوں کا کارکردگی سے موازنہ</h2>\n<p>اسی معیار پر WebP سب سے چھوٹی فائل دیتا ہے، پھر HEIC، پھر JPG۔ JPG سب سے پرانا اور سب سے زیادہ مطابقت رکھنے والا ہے، مگر سب سے کم کارآمد ہے۔</p>\n<p>انتخاب مطابقت اور سائز کے توازن پر منحصر ہے۔ ویب کے لیے WebP، شیئرنگ کے لیے JPG، اور ایپل ڈیوائس پر جگہ بچانے کے لیے HEIC درست رہتا ہے۔</p>\n<h2 id=\"screenshots-suffer-more\">اسکرین شاٹ تصویروں سے زیادہ کیوں خراب ہوتے ہیں</h2>\n<p>اسکرین شاٹ میں تیز کنارے اور صاف متن ہوتا ہے، اور JPG تیز کناروں کو سب سے زیادہ خراب کرتا ہے۔ اسی لیے اسکرین شاٹ JPG میں دھندلا اور ہالہ والا لگتا ہے۔</p>\n<p>اسکرین شاٹ کے لیے PNG یا زیادہ معیار والا WebP چنیں۔ اگر JPG ضروری ہو تو معیار 90 سے اوپر رکھیں، تاکہ متن پڑھنے کے قابل رہے۔</p>\n<h2 id=\"archiving-masters\">مستقبل کے لیے اصل فائلیں محفوظ کرنا</h2>\n<p>آرکائیو کے لیے اصل کو بغیر نقصان والے فارمیٹ میں رکھیں، جیسے PNG یا اصل RAW۔ یہ فائلیں بڑی ہوتی ہیں، مگر یہی مستقبل کی ہر تبدیلی کا صاف ذریعہ ہیں۔</p>\n<p>آرکائیو میں تاریخ اور مقام کے ساتھ نام رکھیں، اور ایک نقل کلاؤڈ میں بھی رکھیں۔ فارمیٹ بدلتے رہتے ہیں، مگر محفوظ اصل ہر نئے فارمیٹ میں بدلی جا سکتی ہے۔ تبدیلی کے عملی مراحل <a href=\"/ur/blog/tasveer-format-kaise-convert-karein/\">تصویر کا فارمیٹ کیسے بدلیں</a> اور مکمل رہنما <a href=\"/ur/blog/tasveer-converter-rehnumai/\">امیج کنورٹر رہنما</a> میں دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا JPG کو WebP میں بدلنے سے معیار کھو جاتا ہے؟","answer":"ہلکا سا نقصان ہوتا ہے، مگر 80 سے 85 معیار پر وہ نظر نہیں آتا۔ WebP JPG سے چھوٹی فائل دیتا ہے، اس لیے ویب کے لیے یہ تبدیلی فائدہ مند ہے۔"},{"question":"ویب سائٹ کے لیے PNG یا WebP میں بدلنا بہتر ہے؟","answer":"زیادہ تر ویب تصویروں کے لیے WebP بہتر ہے، کیونکہ وہ PNG سے بہت چھوٹا ہوتا ہے۔ PNG صرف اس وقت چنیں جب شفافیت کے ساتھ بغیر نقصان والا معیار چاہیے۔"},{"question":"کیا میں کم معیار والی JPG کو زیادہ معیار والی PNG میں بدل سکتا ہوں؟","answer":"نہیں، کھوئی ہوئی تفصیل واپس نہیں آتی۔ PNG صرف وہی بچاتا ہے جو JPG میں باقی ہے، اس لیے فائل بڑی ہو جاتی ہے مگر تصویر بہتر نہیں ہوتی۔"},{"question":"تصویر خراب لگنے سے پہلے میں اسے کتنی بار بدل سکتا ہوں؟","answer":"اصل سے ایک بار بدلنا محفوظ ہے۔ نقل کو بار بار بدلنے سے ہر نسل میں معیار گرتا ہے، اور چار پانچ نسلوں کے بعد خرابی صاف نظر آنے لگتی ہے۔"},{"question":"کیا تصویر بدلنے سے اس کے رنگ متاثر ہوتے ہیں؟","answer":"ہلکا سا فرق آ سکتا ہے، خاص طور پر اگر رنگ پروفائل محفوظ نہ رہے۔ اصل سے بدلتے وقت رنگ پروفائل بچانے والا ٹول استعمال کریں اور نتیجہ اصل سے ملا کر دیکھیں۔"},{"question":"کیا مجھے جگہ بچانے کے لیے اپنی تصویریں HEIC میں بدلنی چاہییں؟","answer":"اپنے فون پر جگہ بچانے کے لیے HEIC اچھا ہے، مگر شیئر کرنے کے لیے نہیں، کیونکہ بہت سے پروگرام اسے نہیں کھولتے۔ شیئر کرنے سے پہلے JPG یا PNG میں بدل لیں۔"}];
